/* Deterministic, fully local Three.js opening. No per-frame assets are created. */
(function () {
  'use strict';

  const canvas = document.createElement('canvas');
  canvas.width = 1920;
  canvas.height = 1080;
  const info = { width: 1920, height: 1080, duration: 7.2, engine: 'Three.js 0.160.1' };
  let renderer, scene, camera, homepageTexture;
  let prices, centerPrice, bowl, noodles, dates, homepage;
  let initialized = false;
  let initPromise;
  const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
  const ease = v => { v = clamp(v); return v * v * (3 - 2 * v); };
  const out = v => 1 - Math.pow(1 - clamp(v), 3);
  const local = (t, a, b) => clamp((t - a) / (b - a));

  function roundedShape(w, h, r) {
    const s = new THREE.Shape();
    const x = -w / 2, y = -h / 2;
    s.moveTo(x + r, y);
    s.lineTo(x + w - r, y);
    s.quadraticCurveTo(x + w, y, x + w, y + r);
    s.lineTo(x + w, y + h - r);
    s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    s.lineTo(x + r, y + h);
    s.quadraticCurveTo(x, y + h, x, y + h - r);
    s.lineTo(x, y + r);
    s.quadraticCurveTo(x, y, x + r, y);
    return s;
  }

  function labelTexture(w, h, paint) {
    const c = document.createElement('canvas');
    c.width = 1024;
    c.height = Math.round(1024 * h / w);
    const q = c.getContext('2d');
    const sx = c.width / w, sy = c.height / h;
    q.scale(sx, sy);
    paint(q, w, h);
    const texture = new THREE.CanvasTexture(c);
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
    texture.needsUpdate = true;
    return texture;
  }

  function text(q, value, x, y, size, color, weight = 600) {
    q.font = `${weight} ${size}px "PingFang SC","Hiragino Sans GB","Arial Unicode MS",sans-serif`;
    q.textAlign = 'center';
    q.textBaseline = 'middle';
    q.fillStyle = color;
    q.fillText(value, x, y);
  }

  function makePlaque(w, h, depth, color, texture) {
    const group = new THREE.Group();
    const geometry = new THREE.ExtrudeGeometry(roundedShape(w, h, 0.18), {
      depth,
      bevelEnabled: true,
      bevelSegments: 3,
      steps: 1,
      bevelSize: 0.045,
      bevelThickness: 0.045,
      curveSegments: 12
    });
    geometry.translate(0, 0, -depth / 2);
    const body = new THREE.Mesh(geometry, new THREE.MeshPhysicalMaterial({
      color,
      roughness: 0.3,
      metalness: 0.04,
      clearcoat: 0.72,
      clearcoatRoughness: 0.25
    }));
    body.castShadow = true;
    body.receiveShadow = true;
    group.add(body);
    const face = new THREE.Mesh(
      new THREE.PlaneGeometry(w - 0.08, h - 0.08),
      new THREE.MeshPhysicalMaterial({
        map: texture,
        transparent: true,
        roughness: 0.42,
        clearcoat: 0.35,
        clearcoatRoughness: 0.32,
        polygonOffset: true,
        polygonOffsetFactor: -1
      })
    );
    face.position.z = depth / 2 + 0.047;
    group.add(face);
    return group;
  }

  function priceTexture(label, price, foot, accent) {
    return labelTexture(3.6, 2.2, (q, w, h) => {
      q.clearRect(0, 0, w, h);
      text(q, label, w / 2, 0.37, 0.22, '#264a3f', 700);
      text(q, price, w / 2, 1.08, 0.76, accent, 800);
      q.fillStyle = '#31584a55';
      q.fillRect(0.54, 1.58, w - 1.08, 0.012);
      text(q, foot, w / 2, 1.85, 0.17, '#426358', 500);
    });
  }

  function dateTexture(day, title, foot, dark) {
    return labelTexture(3.0, 1.8, (q, w, h) => {
      q.clearRect(0, 0, w, h);
      text(q, day, w / 2, 0.35, 0.25, dark ? '#173c33' : '#35594e', 700);
      text(q, title, w / 2, 0.92, 0.38, '#173c33', 800);
      text(q, foot, w / 2, 1.43, 0.18, '#426358', 500);
    });
  }

  function buildPriceCards() {
    prices = new THREE.Group();
    const a = makePlaque(3.6, 2.2, 0.2, '#dce9df',
      priceTexture('A · 不含早餐', '¥1200', '两晚 · 全程总价 · 示例', '#173c33'));
    const b = makePlaque(3.6, 2.2, 0.2, '#efbd73',
      priceTexture('B · 包含早餐', '¥1440', '两晚 · 全程总价 · 示例', '#173c33'));
    a.position.set(-4.05, 2.0, 0);
    b.position.set(4.05, 2.0, 0);
    a.rotation.y = 0.09;
    b.rotation.y = -0.09;
    a.userData.home = a.position.clone();
    b.userData.home = b.position.clone();
    prices.add(a, b);
    prices.userData.a = a;
    prices.userData.b = b;
    scene.add(prices);

    centerPrice = makePlaque(2.9, 1.55, 0.18, '#e9855c', labelTexture(2.9, 1.55, (q, w, h) => {
      q.clearRect(0, 0, w, h);
      text(q, '两晚差价', w / 2, 0.27, 0.2, '#5a2c20', 700);
      text(q, '¥240', w / 2, 0.78, 0.64, '#3e251e', 800);
      text(q, '酒店早餐只吃 1 次', w / 2, 1.3, 0.18, '#542f25', 600);
    }));
    centerPrice.position.set(0, 0.25, 1.65);
    scene.add(centerPrice);
  }

  function buildBowl() {
    bowl = new THREE.Group();
    const profile = [
      [0.0, 0.0], [0.65, 0.0], [0.82, 0.08], [1.02, 0.35],
      [1.25, 0.78], [1.42, 1.22], [1.46, 1.38], [1.43, 1.46],
      [1.34, 1.46], [1.31, 1.36], [1.27, 1.2], [1.12, 0.79],
      [0.91, 0.4], [0.7, 0.22], [0.0, 0.22]
    ].map(p => new THREE.Vector2(p[0], p[1]));
    const ceramic = new THREE.MeshPhysicalMaterial({
      color: '#f4ead8',
      roughness: 0.22,
      metalness: 0,
      clearcoat: 0.9,
      clearcoatRoughness: 0.16,
      side: THREE.DoubleSide
    });
    const vessel = new THREE.Mesh(new THREE.LatheGeometry(profile, 96), ceramic);
    vessel.castShadow = true;
    vessel.receiveShadow = true;
    bowl.add(vessel);

    const rim = new THREE.Mesh(new THREE.TorusGeometry(1.395, 0.052, 12, 96), ceramic);
    rim.rotation.x = Math.PI / 2;
    rim.position.y = 1.415;
    rim.castShadow = true;
    bowl.add(rim);

    const soup = new THREE.Mesh(new THREE.CircleGeometry(1.27, 72), new THREE.MeshPhysicalMaterial({
      color: '#a85f27', roughness: 0.28, clearcoat: 0.8, clearcoatRoughness: 0.18
    }));
    soup.rotation.x = -Math.PI / 2;
    soup.position.y = 1.31;
    bowl.add(soup);

    noodles = new THREE.Group();
    const noodleMaterial = new THREE.MeshPhysicalMaterial({
      color: '#f4d38f', roughness: 0.4, clearcoat: 0.35, clearcoatRoughness: 0.3
    });
    for (let i = 0; i < 11; i++) {
      const points = [];
      const phase = i * 0.71;
      const radius = 0.38 + (i % 4) * 0.2;
      for (let j = 0; j <= 18; j++) {
        const u = j / 18;
        const angle = phase + u * (Math.PI * 1.55 + (i % 3) * 0.35);
        const r = radius * (0.72 + 0.28 * Math.sin(u * Math.PI));
        points.push(new THREE.Vector3(
          Math.cos(angle) * r,
          1.36 + 0.07 * Math.sin(u * Math.PI * 2 + phase) + (i % 3) * 0.025,
          Math.sin(angle) * r * 0.8
        ));
      }
      const curve = new THREE.CatmullRomCurve3(points);
      const strand = new THREE.Mesh(new THREE.TubeGeometry(curve, 72, 0.045, 8, false), noodleMaterial);
      strand.castShadow = true;
      noodles.add(strand);
    }
    bowl.add(noodles);
    bowl.position.set(0, -1.08, 0.55);
    bowl.scale.setScalar(0.001);
    scene.add(bowl);
  }

  function buildDates() {
    dates = new THREE.Group();
    const outCard = makePlaque(3.0, 1.8, 0.16, '#e8eee6',
      dateTexture('11月02日', '留给外出', '外出 · 当地味', false));
    const hotelCard = makePlaque(3.0, 1.8, 0.16, '#efbd73',
      dateTexture('11月03日', '酒店早餐', '酒店 · 1 次', true));
    outCard.position.set(-3.55, 1.55, 0.35);
    hotelCard.position.set(3.55, 1.55, 0.35);
    dates.add(outCard, hotelCard);
    dates.userData.out = outCard;
    dates.userData.hotel = hotelCard;
    dates.visible = false;
    scene.add(dates);
  }

  function buildHomepage() {
    homepage = new THREE.Group();
    const backing = new THREE.Mesh(new THREE.BoxGeometry(8.96, 5.12, 0.1), new THREE.MeshPhysicalMaterial({
      color: '#d8c6a6', roughness: 0.35, clearcoat: 0.55, clearcoatRoughness: 0.3
    }));
    backing.castShadow = true;
    homepage.add(backing);
    const screen = new THREE.Mesh(new THREE.PlaneGeometry(8.8, 4.95), new THREE.MeshPhysicalMaterial({
      map: homepageTexture,
      roughness: 0.5,
      clearcoat: 0.18,
      clearcoatRoughness: 0.45
    }));
    screen.position.z = 0.056;
    homepage.add(screen);
    homepage.position.set(0, -6.2, 2.2);
    homepage.visible = false;
    scene.add(homepage);
  }

  function buildLightsAndGround() {
    scene.background = new THREE.Color('#102e28');
    scene.fog = new THREE.Fog('#102e28', 18, 34);
    const ground = new THREE.Mesh(new THREE.PlaneGeometry(60, 60), new THREE.MeshStandardMaterial({
      color: '#173c33', roughness: 0.92, metalness: 0.02
    }));
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -1.13;
    ground.receiveShadow = true;
    scene.add(ground);

    scene.add(new THREE.HemisphereLight('#ffe5bb', '#09231d', 1.25));
    const key = new THREE.DirectionalLight('#ffd2a1', 4.1);
    key.position.set(-5, 9, 7);
    key.castShadow = true;
    key.shadow.mapSize.set(2048, 2048);
    key.shadow.camera.left = -11;
    key.shadow.camera.right = 11;
    key.shadow.camera.top = 10;
    key.shadow.camera.bottom = -7;
    key.shadow.camera.near = 0.5;
    key.shadow.camera.far = 30;
    key.shadow.bias = -0.00035;
    key.shadow.normalBias = 0.025;
    scene.add(key);
    const fill = new THREE.DirectionalLight('#f4dfc2', 1.7);
    fill.position.set(6, 4, 5);
    scene.add(fill);
    const rim = new THREE.DirectionalLight('#ffb66e', 3.0);
    rim.position.set(2, 6, -7);
    scene.add(rim);
  }

  function setCamera(t) {
    if (t < 3) {
      const u = ease(local(t, 0, 3));
      camera.position.set(0.18 * Math.sin(u * Math.PI), 4.7 - 0.25 * u, 12.8 - 0.35 * u);
      camera.lookAt(0, 1.0, 0);
    } else if (t < 4.8) {
      const u = ease(local(t, 3, 4.8));
      camera.position.set(0, 4.45 - 0.35 * u, 12.45 - 1.35 * u);
      camera.lookAt(0, 0.75 - 0.35 * u, 0.3);
    } else if (t < 6.2) {
      const u = ease(local(t, 4.8, 6.2));
      camera.position.set(0, 4.1 + 0.12 * u, 11.1 + 0.4 * u);
      camera.lookAt(0, 0.4 + 0.18 * u, 0.3);
    } else {
      const u = ease(local(t, 6.2, 7.2));
      camera.position.set(0, 4.22 - 1.2 * u, 11.5 - 1.4 * u);
      camera.lookAt(0, 0.58 + 0.72 * u, 0.8);
    }
  }

  function update(t) {
    t = clamp(Number(t) || 0, 0, 7.2);
    const retreat = ease(local(t, 3, 4.8));
    const a = prices.userData.a, b = prices.userData.b;
    a.position.set(-4.05 - 2.4 * retreat, 2.0 + 0.35 * retreat, -2.1 * retreat);
    b.position.set(4.05 + 2.4 * retreat, 2.0 + 0.35 * retreat, -2.1 * retreat);
    a.rotation.set(-0.08 * retreat, 0.09 + 1.0 * retreat, -0.08 * retreat);
    b.rotation.set(-0.08 * retreat, -0.09 - 1.0 * retreat, 0.08 * retreat);
    const centerRetreat = ease(local(t, 3.15, 4.65));
    centerPrice.position.set(0, 0.25 + 1.0 * centerRetreat, 1.65 - 3.1 * centerRetreat);
    centerPrice.rotation.y = -0.75 * centerRetreat;
    centerPrice.scale.setScalar(1 - 0.28 * centerRetreat);

    const grow = out(local(t, 3.05, 4.7));
    const bowlScale = Math.max(0.001, grow);
    bowl.scale.setScalar(bowlScale);
    bowl.position.y = -1.08;
    noodles.scale.set(1, Math.max(0.001, out(local(t, 3.45, 4.8))), 1);

    const dateIn = out(local(t, 4.75, 5.65));
    dates.visible = t >= 4.7;
    dates.userData.out.position.x = -6.5 + 2.95 * dateIn;
    dates.userData.hotel.position.x = 6.5 - 2.95 * dateIn;
    dates.userData.out.rotation.y = -0.55 * (1 - dateIn);
    dates.userData.hotel.rotation.y = 0.55 * (1 - dateIn);
    dates.position.y = -0.2 * (1 - dateIn);

    const handoff = out(local(t, 6.2, 7.2));
    homepage.visible = t >= 6.2;
    homepage.position.y = -6.2 + 7.55 * handoff;
    homepage.rotation.x = -0.14 * (1 - handoff);
    setCamera(t);
  }

  async function init() {
    if (initialized) return canvas;
    if (initPromise) return initPromise;
    initPromise = (async () => {
      renderer = new THREE.WebGLRenderer({
        canvas,
        antialias: true,
        alpha: false,
        preserveDrawingBuffer: true,
        powerPreference: 'high-performance'
      });
      renderer.setPixelRatio(1);
      renderer.setSize(1920, 1080, false);
      renderer.shadowMap.enabled = true;
      renderer.shadowMap.type = THREE.PCFSoftShadowMap;
      renderer.toneMapping = THREE.ACESFilmicToneMapping;
      renderer.toneMappingExposure = 1.12;
      renderer.outputColorSpace = THREE.SRGBColorSpace;
      scene = new THREE.Scene();
      camera = new THREE.PerspectiveCamera(36, 1920 / 1080, 0.1, 80);
      buildLightsAndGround();
      buildPriceCards();
      buildBowl();
      buildDates();
      // TextureLoader forces CORS mode, which Chrome rejects for file:// images.
      // A plain local Image keeps the opening fully usable without a web server.
      const homepageImage = new Image();
      // Inline the exact local still only for file://, where Chrome taints local WebGL textures.
      const homepageSource = location.protocol === 'file:'
        ? 'data:image/png;base64,'
        : '../../promo-rework/assets/stills/01-input.png';
      homepageImage.src = homepageSource;
      await homepageImage.decode();
      const homepageCanvas = document.createElement('canvas');
      homepageCanvas.width = homepageImage.naturalWidth;
      homepageCanvas.height = homepageImage.naturalHeight;
      homepageCanvas.getContext('2d').drawImage(homepageImage, 0, 0);
      homepageTexture = new THREE.CanvasTexture(homepageCanvas);
      homepageTexture.colorSpace = THREE.SRGBColorSpace;
      homepageTexture.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
      buildHomepage();
      initialized = true;
      render(0);
      return canvas;
    })();
    return initPromise;
  }

  function render(t) {
    if (!initialized) throw new Error('Opening3D.init() must complete before render(t).');
    update(t);
    renderer.render(scene, camera);
    return canvas;
  }

  window.Opening3D = { init, render, canvas, info };
})();
